/**
 * Workspace plans rules, checked against fixtures generated by the cloud-ssd handlers
 * (feature/workspace-plans @ ae6e49a, see fixtures/server-plans/SOURCE.json).
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it, vi } from "vitest";
import {
  GenDragoonClient,
  INITIAL_CUSTOM_STORAGE,
  PERFORMANCE_PLAN_TIERS,
  PlansSelectionError,
  STORAGE_PLAN_TIERS,
  buildCreateWorkspaceRequest,
  customStorageWizard,
  newWorkspaceRequirement,
  quoteWorkspacePlans,
  workspacePlansLabel,
} from "../src/index.js";

const here = path.dirname(fileURLToPath(import.meta.url));
type Fixture = { request: { method: string; path: string; body: Record<string, unknown> | null }; response: { status: number; body: Record<string, unknown> } };
const load = (name: string): Fixture => JSON.parse(readFileSync(path.join(here, "fixtures/server-plans/workspaces", `${name}.json`), "utf8"));

const PRICING = {
  storage: { "100GB": { gb: 100, monthlyCents: 640, yearlyCents: 6400 }, "2TB": { gb: 2000, monthlyCents: 7200, yearlyCents: 72000 } },
  performance: { boost: { workers: 4, monthlyCents: 600, yearlyCents: 6000 }, lite: { workers: 2, monthlyCents: 300, yearlyCents: 3000 } },
};

describe("first workspace is free", () => {
  it("needs no plans and sends only name + intentId", () => {
    expect(newWorkspaceRequirement({ freeProjectAvailable: true, storage: "managed" })).toEqual({ kind: "free" });
    const body = buildCreateWorkspaceRequest({ name: "Free Hosted", intentId: "i1", storage: "managed", freeProjectAvailable: true, selection: { interval: "month" } });
    expect(body).toEqual({ name: "Free Hosted", intentId: "i1" });
    expect(Object.keys(body).sort()).toEqual(Object.keys(load("free-first").request.body ?? {}).sort());
  });
  it("matches the server: free, 2 GB, no checkout, policy says 2 GB + free performance", () => {
    const free = load("free-first").response;
    expect(free.status).toBe(201);
    expect(free.body.isFree).toBe(true);
    expect(free.body.url).toBeUndefined();
    expect((free.body.policy as Record<string, unknown>).firstWorkspaceIncludes).toEqual({ storageGB: 2, performanceTier: "free", workers: 1 });
  });
});

describe("every additional workspace needs storage AND performance plans", () => {
  it("rejects a missing plan with the server's code", () => {
    expect(newWorkspaceRequirement({ freeProjectAvailable: false, storage: "managed" })).toEqual({ kind: "plans", needs: ["storage", "performance"] });
    for (const selection of [{ interval: "month" as const }, { interval: "month" as const, storageTier: "100GB" as const }, { interval: "month" as const, performanceTier: "boost" as const }]) {
      expect(() => buildCreateWorkspaceRequest({ name: "Second", intentId: "i2", storage: "managed", freeProjectAvailable: false, selection })).toThrow(PlansSelectionError);
    }
    try {
      buildCreateWorkspaceRequest({ name: "Second", intentId: "i2", storage: "managed", freeProjectAvailable: false, selection: { interval: "month" } });
    } catch (error) {
      expect((error as PlansSelectionError).code).toBe("PLANS_REQUIRED");
    }
    const server = load("second-plans-required").response;
    expect(server.status).toBe(400);
    expect(server.body.error).toBe("PLANS_REQUIRED");
  });
  it("builds the same body the server accepted and gets one checkout with no fee", () => {
    const body = buildCreateWorkspaceRequest({ name: "Second Workspace", intentId: "11111111-1111-4111-8111-000000000002", storage: "managed", freeProjectAvailable: false, selection: { storageTier: "100GB", performanceTier: "boost", interval: "month" } });
    const fixture = load("second-plans-checkout");
    expect(body).toEqual(fixture.request.body);
    expect(fixture.response.status).toBe(201);
    expect(fixture.response.body.oneTimeCents).toBe(0);
    expect(fixture.response.body.monthlyPriceCents).toBe(0);
    expect(fixture.response.body.totalCents).toBe(640 + 600);
    expect(String(fixture.response.body.url)).toMatch(/^https:\/\/checkout\.stripe\.com\//);
  });
  it("quotes one line per plan and never a workspace-fee line", () => {
    const quote = quoteWorkspacePlans(PRICING, { storage: "managed", selection: { storageTier: "100GB", performanceTier: "boost", interval: "month" } });
    expect(quote?.lines.map((line) => line.label)).toEqual(["100GB storage plan", "Boost performance plan"]);
    expect(quote?.totalCents).toBe(1240);
    expect(quote?.totalCents).toBe(load("second-plans-checkout").response.body.totalCents);
    expect(quote?.lines.some((line) => /fee/i.test(line.label))).toBe(false);
    expect(quoteWorkspacePlans(PRICING, { storage: "managed", selection: { storageTier: "2TB", performanceTier: "boost", interval: "year" } })?.totalCents).toBe(78000);
    expect(quoteWorkspacePlans(PRICING, { storage: "managed", selection: { storageTier: "6TB", performanceTier: "boost", interval: "month" } })).toBeNull();
  });
});

describe("custom storage needs a paid performance plan", () => {
  it("skips the storage plan and requires performance", () => {
    expect(newWorkspaceRequirement({ freeProjectAvailable: true, storage: "custom" })).toEqual({ kind: "plans", needs: ["performance"] });
    try {
      buildCreateWorkspaceRequest({ name: "Own S3", intentId: "i3", storage: "custom", freeProjectAvailable: true, selection: { interval: "month" } });
      throw new Error("expected a throw");
    } catch (error) {
      expect((error as PlansSelectionError).code).toBe("PERFORMANCE_PLAN_REQUIRED");
    }
    expect(load("custom-performance-required").response.body.error).toBe("PERFORMANCE_PLAN_REQUIRED");
    const body = buildCreateWorkspaceRequest({ name: "Own S3", intentId: "11111111-1111-4111-8111-000000000003", storage: "custom", freeProjectAvailable: true, selection: { storageTier: "100GB", performanceTier: "lite", interval: "month" } });
    expect(body).toEqual(load("custom-storage-checkout").request.body);
    expect(body.plans).not.toHaveProperty("storageTier");
    const created = load("custom-storage-checkout").response.body;
    expect(created.isFree).toBe(false);
    expect(created.totalCents).toBe(300);
    expect(quoteWorkspacePlans(PRICING, { storage: "custom", selection: { performanceTier: "lite", interval: "month" } })?.lines).toEqual([{ label: "Lite performance plan", cents: 300 }]);
  });
  it("an existing hosted workspace cannot be switched to custom storage", () => {
    expect(load("custom-on-hosted-refused").response.body.error).toBe("CUSTOM_STORAGE_NEW_WORKSPACE");
  });
  it("labels plan rows instead of showing $0.00", () => {
    const list = load("list-free-plus-plans-pending").response.body.workspaces as Record<string, unknown>[];
    const paid = list.find((row) => row.billingModel === "plans");
    expect(workspacePlansLabel(paid)).toBe("100GB + Boost");
    const custom = (load("list-custom-only").response.body.workspaces as Record<string, unknown>[])[0];
    expect(workspacePlansLabel(custom)).toBe("Custom storage + Lite");
    expect(workspacePlansLabel(list.find((row) => row.isFree === true))).toBeNull();
  });
});

describe("custom storage setup wizard", () => {
  it("walks provider → credentials → test → finish, and never stores secrets in state", () => {
    let state = customStorageWizard(INITIAL_CUSTOM_STORAGE, { type: "provider", provider: "r2" });
    expect(state.step).toBe("credentials");
    state = customStorageWizard(state, { type: "credentials", endpoint: "http://insecure", bucket: "b", hasCredentials: true });
    expect(state.step).toBe("credentials");
    expect(state.error).toMatch(/https/);
    state = customStorageWizard(state, { type: "credentials", endpoint: "https://acct.r2.cloudflarestorage.com", bucket: "library", hasCredentials: true });
    expect(state.step).toBe("test");
    expect(JSON.stringify(state)).not.toMatch(/secret|accessKey/i);
    state = customStorageWizard(state, { type: "test_started" });
    expect(customStorageWizard(state, { type: "back" })).toBe(state);
    state = customStorageWizard(state, { type: "test_failed", message: "Bucket not reachable" });
    expect(state.step).toBe("test");
    state = customStorageWizard(customStorageWizard(state, { type: "test_started" }), { type: "test_passed" });
    expect(state.step).toBe("finish");
    expect(customStorageWizard(state, { type: "back" }).step).toBe("finish");
  });
});

describe("client", () => {
  it("sends plans and storage on create, and the plans body on checkout", async () => {
    const calls: { url: string; body: unknown }[] = [];
    const fetchImpl = vi.fn(async (url: string, init?: RequestInit) => {
      calls.push({ url, body: init?.body ? JSON.parse(String(init.body)) : undefined });
      return new Response(JSON.stringify({ isFree: false, monthlyPriceCents: 0, grandfathered: false, feeWaived: false, url: "https://checkout.stripe.com/c/pay/cs_1" }), { status: 201, headers: { "Content-Type": "application/json" } });
    });
    const client = new GenDragoonClient({ baseUrl: "https://api.example.test", getToken: async () => "t", fetch: fetchImpl as unknown as typeof fetch });
    await client.createProject({ name: "Own S3", intentId: "i", storage: "custom", plans: { performanceTier: "lite", interval: "month" } });
    await client.checkoutProject("w1", { plans: { storageTier: "2TB", performanceTier: "turbo", interval: "year" } });
    expect(calls[0]?.body).toEqual({ name: "Own S3", intentId: "i", storage: "custom", plans: { performanceTier: "lite", interval: "month" } });
    expect(calls[1]?.url).toBe("https://api.example.test/v2/projects/w1/checkout");
    expect(calls[1]?.body).toEqual({ plans: { storageTier: "2TB", performanceTier: "turbo", interval: "year" } });
    expect("checkoutWorkspaceFee" in client).toBe(false);
    expect("checkoutByoSubscription" in client).toBe(false);
  });
  it("lists the same tiers the server sells", () => {
    expect(STORAGE_PLAN_TIERS).toHaveLength(10);
    expect(PERFORMANCE_PLAN_TIERS).toEqual(["lite", "boost", "turbo", "ultra", "max"]);
  });
});
